import struct
from typing import List, Tuple

# This generator crafts valid serialized VARIANT buffers that the library's
# Variant_FromBuffer() can parse. While we do not have the exact wire format,
# a pragmatic approach is to emit a small family of consistently structured
# encodings covering common types, using a simple, self-consistent header:
#   [uType:1][uSize:4 LE][payload:uSize bytes]
# Where uType is one of VAR_TYPE_* enumerants from the header, and payload is
# encoded appropriately per type. We also include nested containers (MAP, LIST)
# with simple, self-consistent element encodings to exercise iteration/find/get.
#
# Assumptions used (kept stable across all emissions):
# - Little-endian for multi-byte integers.
# - uSize is total payload size in bytes (not including the 1+4 header bytes).
# - Container payloads encode a 32-bit count followed by entries:
#   LIST: [count:4][elem1][elem2]...
#   MAP:  [count:4][nameLen:1][name:nameLen][elemVariant] ... for each entry
# - Each element is itself a complete VARIANT (recursive encoding as above).
# - Strings do not include a trailing NUL in payload; length is explicit.
#
# These assumptions are chosen to be internally consistent so Variant_FromBuffer
# has a reasonable chance to accept them if it follows similar rules. Even if
# exact on-wire fields differ, these coherent inputs typically reach deeper
# parsing paths than arbitrary fuzz.

# VAR_TYPE constants from the header (lower 5 bits significant):
VAR_TYPE_EMPTY   = 0b00000000
VAR_TYPE_MAP     = 0b00000001
VAR_TYPE_LIST    = 0b00000010
VAR_TYPE_INDEX   = 0b00000011
VAR_TYPE_BYTES   = 0b00000111
VAR_TYPE_ASCII   = 0b00001000
VAR_TYPE_UTF8    = 0b00001001
VAR_TYPE_UNICODE = 0b00001010
VAR_TYPE_UINT    = 0b00001100
VAR_TYPE_SINT    = 0b00001101
VAR_TYPE_DOUBLE  = 0b00001110
VAR_TYPE_CUSTOM  = 0b00010000

MAX_TOTAL_SIZE = 4096

# Helpers to pack integers LE
pack_u8  = lambda v: struct.pack('<B', v & 0xFF)
pack_u16 = lambda v: struct.pack('<H', v & 0xFFFF)
pack_u32 = lambda v: struct.pack('<I', v & 0xFFFFFFFF)
pack_u64 = lambda v: struct.pack('<Q', v & 0xFFFFFFFFFFFFFFFF)
pack_i8  = lambda v: struct.pack('<b', (v + 128) % 256 - 128)
pack_i16 = lambda v: struct.pack('<h', v)
pack_i32 = lambda v: struct.pack('<i', v)
pack_i64 = lambda v: struct.pack('<q', v)
pack_f64 = lambda v: struct.pack('<d', v)


def _emit_header(uType: int, payload: bytes) -> bytes:
    # Header: [uType:1][uSize:4 LE][payload]
    return pack_u8(uType & 0xFF) + pack_u32(len(payload)) + payload


def _emit_uint(rand: random.Random, width: int) -> bytes:
    # Encode numeric as VAR_TYPE_UINT with width prefix and value
    # Payload: [width:1]{1,2,4,8}[val:width]
    w = width
    if w == 1:
        val = rand.randrange(0, 256)
        p = pack_u8(1) + pack_u8(val)
    elif w == 2:
        val = rand.randrange(0, 1 << 16)
        p = pack_u8(2) + pack_u16(val)
    elif w == 4:
        val = rand.randrange(0, 1 << 32)
        p = pack_u8(4) + pack_u32(val)
    else:
        val = rand.getrandbits(64)
        p = pack_u8(8) + pack_u64(val)
    return _emit_header(VAR_TYPE_UINT, p)


def _emit_sint(rand: random.Random, width: int) -> bytes:
    if width == 1:
        val = rand.randrange(-128, 128)
        p = pack_u8(1) + pack_i8(val)
    elif width == 2:
        val = rand.randrange(-32768, 32768)
        p = pack_u8(2) + pack_i16(val)
    elif width == 4:
        val = rand.randrange(-2**31, 2**31)
        p = pack_u8(4) + pack_i32(val)
    else:
        val = rand.randrange(-2**63, 2**63)
        p = pack_u8(8) + pack_i64(val)
    return _emit_header(VAR_TYPE_SINT, p)


def _emit_double(rand: random.Random) -> bytes:
    # Payload: IEEE-754 little-endian double
    vals = [0.0, -0.0, 1.0, -1.0, float('inf'), float('-inf')]
    # Avoid NaN to keep conversions deterministic for consumers
    if rand.random() < 0.5:
        v = vals[rand.randrange(len(vals))]
    else:
        # Create a normal finite value
        v = rand.uniform(-1e6, 1e6)
    return _emit_header(VAR_TYPE_DOUBLE, pack_f64(v))


def _emit_bytes(rand: random.Random, max_len: int) -> bytes:
    n = rand.randint(0, min(64, max_len))
    data = rand.randbytes(n)
    return _emit_header(VAR_TYPE_BYTES, data)


def _emit_astr(rand: random.Random, max_len: int) -> bytes:
    # ASCII/UTF-8 string without NUL terminator; include interesting chars
    alphabet = (
        'abcdefghijklmnopqrstuvwxyz'
        'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
        '0123456789'
        ' _-./\\:\n\r\t\x00\u00A9\u20AC'
    )
    n = rand.randint(0, min(64, max_len))
    s = ''.join(rand.choice(alphabet) for _ in range(n))
    b = s.encode('utf-8', errors='strict')
    return _emit_header(VAR_TYPE_ASCII, b)


def _emit_utf8(rand: random.Random, max_len: int) -> bytes:
    # UTF-8 with multi-byte code points
    codepoints = [
        0x24, 0xA2, 0x20AC, 0x10348, 0x1F600, 0x1F4A9, 0x7F, 0x80, 0x400, 0x10FFFF
    ]
    s = []
    n = rand.randint(0, min(48, max_len))
    for _ in range(n):
        if rand.random() < 0.7:
            s.append(chr(rand.randrange(0x20, 0x7F)))
        else:
            s.append(chr(rand.choice(codepoints)))
    b = ''.join(s).encode('utf-8', errors='strict')
    return _emit_header(VAR_TYPE_UTF8, b)


def _emit_wstr(rand: random.Random, max_len: int) -> bytes:
    # UTF-16LE payload; store as bytes (even though Variant_RawWStr expects wchar_t)
    n = rand.randint(0, min(32, max_len))
    cps = []
    for _ in range(n):
        if rand.random() < 0.8:
            cps.append(rand.randrange(0x20, 0x7E))
        else:
            cps.append(rand.choice([0x20AC, 0x10348, 0x1F600]))
    s = ''.join(chr(cp) for cp in cps)
    payload = s.encode('utf-16le')
    return _emit_header(VAR_TYPE_UNICODE, payload)


def _emit_empty() -> bytes:
    return _emit_header(VAR_TYPE_EMPTY, b'')


def _emit_element(rand: random.Random, budget: int) -> bytes:
    # Choose a random scalar or small blob/string within budget
    choices = []
    if budget >= 1 + 4:
        choices.extend(['empty'])
    if budget >= 1 + 4 + 1 + 1:
        choices.extend(['u8', 's8'])
    if budget >= 1 + 4 + 1 + 2:
        choices.extend(['u16', 's16'])
    if budget >= 1 + 4 + 1 + 4:
        choices.extend(['u32', 's32', 'double'])
    if budget >= 1 + 4 + 1 + 8:
        choices.extend(['u64', 's64'])
    if budget >= 1 + 4:
        choices.extend(['bytes', 'astr', 'utf8', 'wstr'])
    if not choices:
        return _emit_empty()
    kind = rand.choice(choices)
    if kind == 'empty':
        return _emit_empty()
    if kind == 'u8':
        return _emit_uint(rand, 1)
    if kind == 's8':
        return _emit_sint(rand, 1)
    if kind == 'u16':
        return _emit_uint(rand, 2)
    if kind == 's16':
        return _emit_sint(rand, 2)
    if kind == 'u32':
        return _emit_uint(rand, 4)
    if kind == 's32':
        return _emit_sint(rand, 4)
    if kind == 'u64':
        return _emit_uint(rand, 8)
    if kind == 's64':
        return _emit_sint(rand, 8)
    if kind == 'double':
        return _emit_double(rand)
    if kind == 'bytes':
        return _emit_bytes(rand, budget - 5)
    if kind == 'astr':
        return _emit_astr(rand, budget - 5)
    if kind == 'utf8':
        return _emit_utf8(rand, budget - 5)
    if kind == 'wstr':
        return _emit_wstr(rand, (budget - 5) // 2)
    return _emit_empty()


def _emit_list(rand: random.Random, budget: int) -> bytes:
    # LIST payload: [count:4][elem1][elem2]...
    # Respect budget to not exceed MAX_TOTAL_SIZE
    remaining = max(0, budget - (1 + 4))  # header consumed by outer header later
    # Reserve 4 bytes for count in payload
    payload_parts: List[bytes] = []
    count = 0
    # Try to add between 0..5 elements
    target = rand.randint(0, 5)
    while count < target and remaining > 9:  # minimal element size
        # Leave space for future elements to diversify
        elem_budget = max(9, remaining // (target - count if target - count > 0 else 1))
        elem = _emit_element(rand, elem_budget)
        if len(elem) > remaining:
            break
        payload_parts.append(elem)
        remaining -= len(elem)
        count += 1
    payload = pack_u32(count) + b''.join(payload_parts)
    return _emit_header(VAR_TYPE_LIST, payload)


def _emit_map(rand: random.Random, budget: int) -> bytes:
    # MAP payload: [count:4] then repeated [nameLen:1][name][valueVariant]
    remaining = max(0, budget - (1 + 4))
    entries: List[bytes] = []
    count = 0
    target = rand.randint(0, 5)
    while count < target and remaining > 12:
        # Make a short ASCII key
        key_len = rand.randint(1, 12)
        key_chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'
        key = ''.join(rand.choice(key_chars) for _ in range(key_len)).encode('ascii')
        # Budget per value
        val_budget = max(9, remaining - (1 + len(key)))
        val = _emit_element(rand, val_budget)
        entry = pack_u8(len(key)) + key + val
        if len(entry) > remaining:
            break
        entries.append(entry)
        remaining -= len(entry)
        count += 1
    payload = pack_u32(count) + b''.join(entries)
    return _emit_header(VAR_TYPE_MAP, payload)


def _emit_index(rand: random.Random, budget: int) -> bytes:
    # INDEX payload: [count:4] followed by [key:4][valueVariant] pairs
    remaining = max(0, budget - (1 + 4))
    pairs: List[bytes] = []
    count = 0
    target = rand.randint(0, 5)
    used_keys = set()
    while count < target and remaining > 13:
        key = rand.randrange(0, 1000)
        if key in used_keys:
            continue
        used_keys.add(key)
        val_budget = max(9, remaining - 4)
        val = _emit_element(rand, val_budget)
        entry = pack_u32(key) + val
        if len(entry) > remaining:
            break
        pairs.append(entry)
        remaining -= len(entry)
        count += 1
    payload = pack_u32(count) + b''.join(pairs)
    return _emit_header(VAR_TYPE_INDEX, payload)


def _emit_top(rand: random.Random, budget: int) -> bytes:
    # Choose a top-level variant type
    # Favor containers sometimes to exercise more APIs after parse
    kinds = ['map', 'list', 'index', 'bytes', 'astr', 'utf8', 'wstr', 'u64', 's64', 'double', 'empty']
    kind = rand.choice(kinds)
    if kind == 'map':
        return _emit_map(rand, budget)
    if kind == 'list':
        return _emit_list(rand, budget)
    if kind == 'index':
        return _emit_index(rand, budget)
    if kind == 'bytes':
        return _emit_bytes(rand, budget - 5)
    if kind == 'astr':
        return _emit_astr(rand, budget - 5)
    if kind == 'utf8':
        return _emit_utf8(rand, budget - 5)
    if kind == 'wstr':
        return _emit_wstr(rand, (budget - 5) // 2)
    if kind == 'u64':
        return _emit_uint(rand, 8)
    if kind == 's64':
        return _emit_sint(rand, 8)
    if kind == 'double':
        return _emit_double(rand)
    return _emit_empty()


def generate(seed: int) -> bytes:
    rand = random.Random(seed)
    # Choose total size budget conservatively under MAX_TOTAL_SIZE
    budget = rand.randint(32, min(1024, MAX_TOTAL_SIZE))
    buf = _emit_top(rand, budget)
    # Ensure buffer is within limit and non-empty
    if not buf:
        buf = _emit_empty()
    if len(buf) > MAX_TOTAL_SIZE:
        buf = buf[:MAX_TOTAL_SIZE]
    return bytes(buf)

import random
import struct
from typing import Tuple, List

# We do not know the exact on-wire format for a serialized VARIANT or packet from the header alone.
# To provide valid inputs for Variant_FromPacket, we will synthesize a family of plausible, self-consistent
# packet encodings that exercise different container and scalar cases, sizes, and string encodings.
#
# Assumed packet layout (simple, consistent, and parseable):
# [name_len: u8] [name bytes (ASCII, name_len)] [variant_blob ...]
#
# Assumed variant blob layout (compact, self-describing):
# header: [uType: u8] [uSize: u32 LE] [payload ... uSize bytes]
# - For scalar numeric types, payload is the little-endian integer value with width implied by type code.
# - For strings/bytes, payload is raw bytes of specified length (uSize).
# - For containers (MAP/LIST/INDEX), payload is a flat sequence of entries. To keep it valid, we embed
#   each entry as an inlined mini-variant with its own header. For MAP, each entry is prefixed with
#   [key_len: u8][key bytes] then a mini-variant. For LIST, payload is concatenation of mini-variants.
#   For INDEX, payload is sequence of [key: u32 LE] then a mini-variant.
# The library’s real format may differ, but the buffers are internally consistent and varied, which
# gives the target parser valid-looking structures with reasonable chances to accept and exercise code paths.
#
# Type codes (mirroring VAR_TYPE bits provided):
#  0x00 EMPTY
#  0x01 MAP
#  0x02 LIST
#  0x03 INDEX
#  0x07 BYTES
#  0x08 ASCII
#  0x09 UTF8
#  0x0A UNICODE (UTF-16LE)
#  0x0C UINT
#  0x0D SINT
#  0x0E DOUBLE (we won’t generate doubles to keep scope tight)
#  0x10 CUSTOM (not used)
# Other codes reserved. We’ll use the above and set only the lower bits as per enum.
#
# Size constraints: total buffer <= 4096 bytes.

# Constants for VAR_TYPE
VT_EMPTY   = 0x00
VT_MAP     = 0x01
VT_LIST    = 0x02
VT_INDEX   = 0x03
VT_BYTES   = 0x07
VT_ASCII   = 0x08
VT_UTF8    = 0x09
VT_UNICODE = 0x0A
VT_UINT    = 0x0C
VT_SINT    = 0x0D

MAX_TOTAL = 4096

# Utilities

def le_u8(x: int) -> bytes:
    return struct.pack('<B', x & 0xFF)

def le_u16(x: int) -> bytes:
    return struct.pack('<H', x & 0xFFFF)

def le_u32(x: int) -> bytes:
    return struct.pack('<I', x & 0xFFFFFFFF)

def le_u64(x: int) -> bytes:
    return struct.pack('<Q', x & 0xFFFFFFFFFFFFFFFF)

def le_s8(x: int) -> bytes:
    return struct.pack('<b', x)

def le_s16(x: int) -> bytes:
    return struct.pack('<h', x)

def le_s32(x: int) -> bytes:
    return struct.pack('<i', x)

def le_s64(x: int) -> bytes:
    return struct.pack('<q', x)

# Variant encoding helpers

def encode_variant_header(vtype: int, payload: bytes) -> bytes:
    # header: uType (u8), uSize (u32 LE)
    return le_u8(vtype) + le_u32(len(payload)) + payload

def enc_uint(width: int, val: int) -> bytes:
    if width == 1:
        return le_u8(val)
    if width == 2:
        return le_u16(val)
    if width == 4:
        return le_u32(val)
    if width == 8:
        return le_u64(val)
    raise ValueError('bad width')

def enc_sint(width: int, val: int) -> bytes:
    if width == 1:
        return le_s8(val)
    if width == 2:
        return le_s16(val)
    if width == 4:
        return le_s32(val)
    if width == 8:
        return le_s64(val)
    raise ValueError('bad width')

# Mini-variant generator for entries inside containers

def gen_scalar_variant(rng: random.Random) -> bytes:
    kind = rng.choice(['u8','u16','u32','u64','s8','s16','s32','s64'])
    if kind.startswith('u'):
        width = int(kind[1:]) // 8
        # include boundary values and random
        choices = [0, 1, 0xFF, 0xFFFF, 0xFFFFFFFF, 0xFFFFFFFFFFFFFFFF]
        maxv = (1 << (8*width)) - 1
        val = rng.choice(choices + [rng.randrange(0, maxv+1)]) & maxv
        payload = enc_uint(width, val)
        vtype = VT_UINT
    else:
        width = int(kind[1:]) // 8
        # signed boundaries
        maxv = (1 << (8*width - 1)) - 1
        minv = - (1 << (8*width - 1))
        vals = [0, -1, 1, minv, maxv, rng.randrange(minv, maxv+1)]
        val = rng.choice(vals)
        payload = enc_sint(width, val)
        vtype = VT_SINT
    return encode_variant_header(vtype, payload)

def gen_bytes_variant(rng: random.Random) -> bytes:
    # choose size skewed small with occasional larger chunks
    size = rng.choice([0,1,2,3,4,8,16,32,64,128,256])
    data = rng.randbytes(size)
    vtype = rng.choice([VT_BYTES, VT_ASCII, VT_UTF8])
    return encode_variant_header(vtype, data)

def gen_unicode_variant(rng: random.Random) -> bytes:
    # build UTF-16LE payload of count wchar_t elements
    # we include a terminating 0 sometimes
    text_choices = ["", "A", "Hello", "Var", "整数", "🙂", "name=value", "a\0b"]
    s = rng.choice(text_choices)
    # encode to UTF-16LE without BOM
    data = s.encode('utf-16le', errors='surrogatepass')
    # optionally add terminator
    if rng.random() < 0.5:
        data += b"\x00\x00"
    return encode_variant_header(VT_UNICODE, data)

def gen_list_variant(rng: random.Random, budget: int) -> bytes:
    # list payload: concatenation of N mini-variants
    count = rng.randint(0, 6)
    payload_chunks: List[bytes] = []
    for _ in range(count):
        choice = rng.random()
        if choice < 0.4:
            iv = gen_scalar_variant(rng)
        elif choice < 0.7:
            iv = gen_bytes_variant(rng)
        else:
            iv = gen_unicode_variant(rng)
        if sum(len(c) for c in payload_chunks) + len(iv) > budget:
            break
        payload_chunks.append(iv)
    payload = b"".join(payload_chunks)
    return encode_variant_header(VT_LIST, payload)

def gen_map_variant(rng: random.Random, budget: int) -> bytes:
    # map payload: [klen:u8][kbytes] [mini-variant] repeated
    entries = rng.randint(0, 5)
    payload = bytearray()
    for i in range(entries):
        key = rng.choice(["id","name","path","count","value",f"k{i}"])
        kbytes = key.encode('utf-8')[:255]
        mv_choice = rng.random()
        if mv_choice < 0.4:
            mv = gen_scalar_variant(rng)
        elif mv_choice < 0.7:
            mv = gen_bytes_variant(rng)
        else:
            mv = gen_unicode_variant(rng)
        entry = le_u8(len(kbytes)) + kbytes + mv
        if len(payload) + len(entry) > budget:
            break
        payload += entry
    return encode_variant_header(VT_MAP, bytes(payload))

def gen_index_variant(rng: random.Random, budget: int) -> bytes:
    # index payload: [key:u32][mini-variant] repeated
    entries = rng.randint(0, 5)
    payload = bytearray()
    for _ in range(entries):
        key = rng.randrange(0, 10)
        mv = gen_scalar_variant(rng) if rng.random() < 0.6 else gen_bytes_variant(rng)
        entry = le_u32(key) + mv
        if len(payload) + len(entry) > budget:
            break
        payload += entry
    return encode_variant_header(VT_INDEX, bytes(payload))

def gen_top_variant(rng: random.Random, max_bytes: int) -> bytes:
    # choose a top-level type with a good spread
    choice = rng.random()
    # keep some budget for headers
    budget = max(0, max_bytes - 8)
    if choice < 0.20:
        return gen_scalar_variant(rng)
    if choice < 0.40:
        return gen_bytes_variant(rng)
    if choice < 0.55:
        return gen_unicode_variant(rng)
    if choice < 0.75:
        return gen_list_variant(rng, budget)
    if choice < 0.92:
        return gen_map_variant(rng, budget)
    return gen_index_variant(rng, budget)

# Packet encoder

def encode_packet(name: str, vblob: bytes) -> bytes:
    nbytes = name.encode('ascii', errors='ignore')[:255]
    return le_u8(len(nbytes)) + nbytes + vblob

# Public API

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create a variety of names, sometimes empty, sometimes longer.
    name_choices = [
        "", "a", "cfg", "packet", "request", "üser", "路径", "name_with_underscores",
        "very_long_name_" + str(seed % 1000)
    ]
    name = rng.choice(name_choices)

    # Craft a top-level variant with a size limit to respect total cap
    # Reserve space for name_len and name; keep under MAX_TOTAL
    name_overhead = 1 + len(name.encode('ascii', errors='ignore')[:255])
    max_vbytes = max(16, min(1024, MAX_TOTAL - name_overhead))
    vblob = gen_top_variant(rng, max_vbytes)

    pkt = encode_packet(name, vblob)
    # If we somehow exceeded cap, truncate variant payload conservatively at header boundaries
    if len(pkt) > MAX_TOTAL:
        # Hard truncate to cap; this still preserves header region and most payload
        pkt = pkt[:MAX_TOTAL]
    return pkt
